export function normalizeLocationCode(str: string): string {
  if (!str) return '';
  const trimmed = str.trim().toUpperCase();
  const parts = trimmed.split('-');
  if (parts.length === 4) {
    const aisle = parts[0];
    const rack = parts[1];
    const level = parts[2].padStart(2, '0');
    const position = parts[3].padStart(2, '0');
    return `${aisle}-${rack}-${level}-${position}`;
  }
  return trimmed;
}

export function isUuid(str?: string | null): boolean {
  if (!str || typeof str !== 'string') return false;
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(str.trim());
}

export function resolveLocationUuid(idOrCode?: string | null): string {
  if (!idOrCode) return '';
  const trimmed = idOrCode.trim();
  if (isUuid(trimmed)) return trimmed;
  const normalized = normalizeLocationCode(trimmed);
  return LOCATION_CODE_TO_UUID[normalized] || LOCATION_CODE_TO_UUID[trimmed] || trimmed;
}

export function getWarehouseSeedLocations(): Location[] {
  const rackDefs = [
    { code: 'C', name: 'Rack Central', levels: 2, positions: 15 },
    { code: 'P', name: 'Rack Pared', levels: 2, positions: 22 },
  ];
  return ['A', 'B'].flatMap((aisleCode) =>
    rackDefs.flatMap((def) =>
      Array.from({ length: def.levels }, (_, l) => l + 1).flatMap((level) =>
        Array.from({ length: def.positions }, (_, p) => p + 1).map((position) => {
          const code = `${aisleCode}-${def.code}-${String(level).padStart(2, '0')}-${String(position).padStart(2, '0')}`;
          const id = LOCATION_CODE_TO_UUID[code] || `${aisleCode}-${def.code}-${level}-${position}`;
          return {
            id,
            code,
            status: 'AVAILABLE',
            level,
            position,
            rack: {
              id: `rack-${aisleCode}-${def.code}`,
              code: def.code,
              name: def.name,
              levels: def.levels,
              positions: def.positions,
              aisle: { code: aisleCode },
            },
          };
        })
      )
    )
  );
}
